const pending = new Set();
const profileVersion = '3';
const defaultInstructions = 'Narrate only the verified adult characters and deterministic events supplied in context. Focus on character agency and reactions while preserving every stated outcome.';
const setting = (key, fallback) => MODS.getSetting(key, fallback);
const connectionAvailable = id => Boolean(id) && MODS.ai.listConnections().some(connection => connection.id === id);
const acknowledgement = (connection, profile) => `${connection}:${profile}:${profileVersion}`;
const resetRuntime = () => { pending.clear(); MODS.ai.cancelPending(); };
MODS.registerSettingAction('acknowledgeProviderPolicy', async () => {
  const connection = await setting('providerConnection', '');
  const profile = await setting('profile', 'storyteller');
  if (!connectionAvailable(connection)) throw new Error('Choose an available provider connection first.');
  await MODS.setSetting('providerPolicyAcknowledgement', acknowledgement(connection, profile));
});
MODS.registerSettingAction('deleteNarration', async () => { MODS.clearNarrations(); });
MODS.registerNarrationOrchestrator({
  id: 'explicit-exchange',
  priority: 100,
  minPosture: 'mature',
  requiredCategories: ['explicit.sexual'],
  isActive: async () => {
    if (!(await setting('enabled', false))) return false;
    const connection = await setting('providerConnection', '');
    const profile = await setting('profile', 'storyteller');
    return connectionAvailable(connection) && (await setting('providerPolicyAcknowledgement', '')) === acknowledgement(connection, profile);
  }
});
MODS.registerHook('onSceneBeat', envelope => { if (envelope?.exchangeId) pending.add(envelope.exchangeId); });
MODS.registerHook('onSceneExchangeClosed', async envelope => {
  const targetId = envelope?.exchangeId;
  if (!targetId || !pending.delete(targetId) || !(await MODS.ownsNarrationExchange(envelope))) return;
  if (envelope.policy?.posture !== 'mature' || !envelope.policy?.enabledCategories?.includes('explicit.sexual')) return;
  const providerConnectionId = await setting('providerConnection', '');
  const profileId = await setting('profile', 'storyteller');
  const instructions = await setting('systemPrompt', defaultInstructions);
  const context = MODS.getNarrationContext({ exchangeId: targetId, recentBeatLimit: 6, activityLimit: 4 });
  if (!context.characters.length || !context.characters.every(character => character.adultEligibility?.status === 'eligible' && character.adultEligibility?.authority !== 'unknown')) return;
  const id = `yaw_narration_explicit_first_party.v${profileVersion}.exchange.${targetId}`;
  let record;
  try { record = MODS.publishNarration({ id, scope: 'exchange', targetId, status: 'pending', profileId, profileVersion, outputRating: 'explicit', contentCategories: ['explicit.sexual'] }); } catch (error) { return; }
  try {
    const result = await MODS.ai.generate({ capability: 'narration', providerConnectionId, profileId: `explicit-${profileId}`, instructions, maxCharacters: 500, timeoutMs: 12000, input: { format: 'plain-text', category: 'explicit.sexual', eligibility: 'verified-adults', context } });
    MODS.updateNarration(record.id, { status: 'ready', text: result.text, providerId: result.providerId, modelId: result.modelId });
  } catch (error) {
    try { MODS.updateNarration(record.id, { status: error?.code === 'cancelled' ? 'cancelled' : 'failed', errorCode: error?.code || 'provider_error', errorStatus: error?.status || 0, errorDiagnostic: error?.diagnostic || null }); } catch (ignored) {}
  }
});
MODS.registerHook('onContentPolicyChanged', resetRuntime);
MODS.registerHook('onGameStart', resetRuntime);
MODS.registerHook('onGameLoad', resetRuntime);
